WITH base AS (SELECT *, ROUND(quantity * 1.15, 2) AS quantity_scaled FROM order_items WHERE product_id IS NULL) SELECT *, RANK() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC) AS quantity_rank, NTILE(3) OVER (ORDER BY quantity_scaled DESC, id) AS quantity_scaled_bucket, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity FROM base;
